INSERT INTO "semantic_terms" ("id", "label", "description", "synonyms", "source", "feed_path", "mapped_columns", "unit", "params", "certified") VALUES
  ('supertrend', 'SuperTrend', 'SuperTrend (TradingView ta.supertrend): an ATR band around hl2 that ratchets with the trend and flips when the close crosses it. Defaults: ATR length 10, factor 3. Vertex stores no SuperTrend series. Compute it in a chart script with [line, dir] = ta.supertrend(3, 10), where dir is -1 in an up trend and +1 in a down trend (TradingView sign), or with the script template "SuperTrend" or the chart study "SuperTrend 10, 3". Research code: services/research/indicators/trend.py supertrend (direction +1 up, -1 down).', '["Super Trend", "supertrend 10 3", "ATR trend line"]'::jsonb, 'none', null, '[]'::jsonb, 'price', '[]'::jsonb, false),
  ('ultimate_ma', 'Ultimate MA', 'Ultimate MA (ChrisMoody CM_Ultimate_MA_MTF_V2): one moving average of 8 types (SMA, EMA, WMA, Hull, VWMA, RMA, TEMA, Tilson T3), rising (green) when its value is at or above its value 2 bars ago. Default: SMA 20. Vertex stores no series for it. Use the script template "Ultimate MA (8 types)" (input maType 1-8) or the chart study "Ultimate MA SMA 20"; in the strategy DSL the default is sma(20) >= sma(20, offset 2).', '["Ultimate Moving Average", "UMA", "CM Ultimate MA", "ultimate ma"]'::jsonb, 'none', null, '[]'::jsonb, 'price', '[]'::jsonb, false),
  ('alphatrend', 'AlphaTrend', 'AlphaTrend (KivancOzbilgic): an ATR band (simple mean of true range, length 14, coefficient 1) that moves up only while the Money Flow Index of hlc3 is at or above 50 and down only below it, so it stays flat in choppy markets; the RSI of the close replaces the MFI for data without volume (the chart study switches by itself; in the script template turn off the input "Use MFI"). Rising when it is above its value 2 bars ago. Vertex stores no series for it. Use the script template "AlphaTrend" or the chart study "AlphaTrend 14, 1 (MFI)".', '["Alpha Trend", "alpha trend indicator"]'::jsonb, 'none', null, '[]'::jsonb, 'price', '[]'::jsonb, false),
  ('chandelier_exit', 'Chandelier Exit', 'Chandelier Exit (Chuck LeBeau; everget ratcheting form): a long stop at the highest high of 22 bars minus 3 x ATR(22) and a short stop at the lowest low plus 3 x ATR(22); the direction turns up when the close is above the previous short stop and down when it is below the previous long stop. Vertex stores no series for it. Use the script template "Chandelier Exit" or the chart study "Chandelier Exit 22, 3".', '["Chandelier", "chandelier stop", "ATR trailing exit"]'::jsonb, 'none', null, '[]'::jsonb, 'price', '[]'::jsonb, false),
  ('slingshot', 'Slingshot', 'Slingshot (ChrisMoody CM Sling Shot System): EMA 38 against EMA 62 of the close; up when the 38 is above the 62, down when below. Used as a trend filter. Vertex stores no series for it. Use the script template "Slingshot (EMA 38/62)" or the chart study "Slingshot EMA 38, 62"; in the strategy DSL it is ema(38) > ema(62).', '["Sling Shot", "sling shot system", "EMA 38/62", "EMA 38 62"]'::jsonb, 'none', null, '[]'::jsonb, 'price', '[]'::jsonb, false)
